// Relational Integrity Demo (PK/FK) - bisa dijalankan di console
const students = [ { id: 1, name: 'Budi', courseId: 'IF101' }, { id: 2, name: 'Siti', courseId: 'IF102' } ];
const courses = [ { courseId: 'IF101', title: 'Sistem Basis Data' }, { courseId: 'IF102', title: 'Struktur Data' } ];

function checkPKUnique(rows, pkField) {
  const seen = new Set();
  for (const r of rows) {
    if (seen.has(r[pkField])) return { ok: false, message: 'PK duplikat: ' + r[pkField] };
    seen.add(r[pkField]);
  }
  return { ok: true, message: 'PK unik untuk field: ' + pkField };
}

function checkFKValid(childRows, fkField, parentRows, parentPkField) {
  const parentKeys = new Set(parentRows.map(r => r[parentPkField]));
  for (const r of childRows) {
    const fkVal = r[fkField];
    if (!parentKeys.has(fkVal)) {
      return { ok: false, message: 'FK tidak valid: ' + fkField + '=' + fkVal + ' tidak ada di parent' };
    }
  }
  return { ok: true, message: 'Semua FK valid untuk field: ' + fkField };
}

const pkResult = checkPKUnique(students, 'id');
console.log(pkResult.message);

const fkResult = checkFKValid(students, 'courseId', courses, 'courseId');
console.log(fkResult.message);

