// Three-schema mapper simulation (Eksternal -> Konseptual)
const externalUserView = [ { nama: 'Budi', tanggalLulus: '2026-09-27' } , { nama: 'Siti', tanggalLulus: '2026-10-01' } ];

// Konseptual skema: atribut yang dipakai secara logis di seluruh sistem
const conceptualSchemaFields = ['studentName', 'graduationDate'];

// Mapping dari eksternal ke konseptual
const mappingExternalToConceptual = { nama: 'studentName', tanggalLulus: 'graduationDate' };

function mapRow(externalRow) {
  const conceptualRow = {};
  for (const [extKey, conceptKey] of Object.entries(mappingExternalToConceptual)) {
    conceptualRow[conceptKey] = externalRow[extKey];
  }
  // opsional: pastikan semua field konseptual terisi
  return conceptualRow;
}

const conceptualRows = externalUserView.map(mapRow);
console.log('Konseptual hasil mapping:', conceptualRows);

